const app=document.querySelector('#app'), KEY='neon-psyche-v1';
let answers=Array(30).fill(null),current=0,sound=false,audioContext;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&saved.answers?.length===30&&saved.answers.every(v=>v===null||[-2,-1,0,1,2].includes(v))){answers=saved.answers;current=Math.max(0,Math.min(29,Number(saved.current)||0));}}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,answers,current}));}catch{}}
function beep(){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.value=330+current*12;g.gain.setValueAtTime(.025,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.08);o.start();o.stop(audioContext.currentTime+.09);}catch{}}
const complete=()=>answers.every(v=>v!==null);
function go(render){render();window.scrollTo({top:0,behavior:'smooth'});app.querySelector('h1, h2')?.focus({preventScroll:true});}
function home(){const count=answers.filter(v=>v!==null).length;app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-cross">+</span> PERSONALITY AUDIT PROTOCOL / V.2.077</div><h1 tabindex="-1">你的灵魂，<br>是哪一种<span class="outlined">故障</span><span class="accent">？</span></h1><p class="hero-sub">在这个连梦境都要订阅的时代，<br>至少，你还可以免费审视一下自己。</p><p class="hero-desc">30 道来自系统边缘的拷问。关于权力、自由、虚无，<br class="desktop">以及你为什么还没掀桌。没有标准答案，只有你的底层代码。</p><button class="primary" id="start">${count?(complete()?'查看我的人格档案':'继续审计 · '+count+'/30'):'开始人格审计'} <span>↗</span></button><div class="hero-meta"><span>◷ 约 5–8 分钟</span><span>⊙ 无需登录</span><span>↳ 数据留在本机</span></div></div><div class="art-panel"><div class="art-top mono"><span>SUBJECT_0001</span><span class="accent">● AWAITING SCAN</span></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="scanline"></div><svg class="head-art" viewBox="0 0 400 450" fill="none" aria-label="由绿色线条组成的赛博格头像" role="img"><defs><pattern id="grid" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M18 0H0V18" stroke="#c5fa3c" stroke-width=".6"/></pattern><clipPath id="head"><path d="M104 172Q96 68 198 50Q294 39 305 144L301 207L329 251L299 264L294 314L246 332L248 381L139 376L152 309Q99 271 104 172Z"/></clipPath></defs><g stroke="#c5fa3c"><path d="M104 172Q96 68 198 50Q294 39 305 144L301 207L329 251L299 264L294 314L246 332L248 381L139 376L152 309Q99 271 104 172Z" fill="#172219" stroke-width="2"/><g clip-path="url(#head)"><rect x="80" y="40" width="260" height="350" fill="url(#grid)"/><path d="M109 148L203 64L295 151L154 302L113 185L273 102L288 309L134 232L244 332L166 76L304 207L104 172M140 376L250 264L112 112L301 207L152 309L198 50L294 314M105 208L301 146M108 244L300 182M125 280L308 228" stroke-width=".8"/></g><path d="M239 192L294 192L287 211L246 209Z" fill="#c5fa3c"/><path d="M244 290L288 290M133 391H267M123 399H277"/><circle cx="159" cy="194" r="32" fill="#10180f"/><circle cx="159" cy="194" r="22"/><path d="M159 165V223M130 194H188M182 172L217 150H340M184 214L224 239H350"/><circle cx="159" cy="194" r="8" fill="#c5fa3c"/><path d="M72 75V50H98M315 50H340V75M72 347V372H98M315 372H340V347" stroke-width="2"/></g><g fill="#c5fa3c" font-family="monospace" font-size="9"><text x="224" y="143">COGNITIVE DISSONANCE</text><text x="231" y="254">EGO_CORE / ONLINE</text><text x="38" y="430">[ HUMAN? ]</text><text x="274" y="430">SCAN_07:77</text></g></svg><div class="art-bottom mono"><span>神经接口连接中_</span><span>灵魂纯度：未知</span></div><div class="art-sticker">100% 人类*<small>*结果仅供怀疑</small></div></div></section><div class="ticker" aria-hidden="true"><span>QUESTION EVERYTHING</span> ✳ <span>你不是你的工号</span> ✳ <span>SYSTEM IS A SOCIAL CONSTRUCT</span> ✳ <span>保持怀疑，继续呼吸</span> ✳</div><section class="below"><div class="section-label"><span class="eyebrow">WHAT'S UNDER YOUR SKIN</span><h2>拆开你，看看里面是什么。</h2></div><div class="feature-grid"><article><span class="feature-num">01 /</span><h3>不太礼貌的提问 <span>↗</span></h3><p>从财富分配到存在危机。跳过“你喜欢什么颜色”，直接问问你的世界观。</p><div class="tag">30 道灵魂质询</div></article><article><span class="feature-num">02 /</span><h3>不止一个人格标签 <span>⌘</span></h3><p>五个维度描绘你的思想坐标。人类很复杂，四个字母可能装不下。</p><div class="tag">多维倾向分析</div></article><article><span class="feature-num">03 /</span><h3>一份精神故障报告 <span>✳</span></h3><p>认领你的夜城人格，看看你的理想、矛盾，以及系统眼中的“异常”。</p><div class="tag">专属人格档案</div></article></div><p class="disclaimer">⚑ 娱乐与自我探索用途。不是心理诊断，也不是政治立场鉴定。系统嘴欠，但你不必认同它。</p></section>`;document.querySelector('#start').onclick=()=>go(complete()?result:quiz);}
function quiz(){const q=QUESTIONS[current],count=answers.filter(v=>v!==null).length;app.innerHTML=`<section class="quiz-shell"><div class="quiz-top"><button class="text-button" id="exit">← 返回控制台</button><span class="mono">AUDIT IN PROGRESS <span class="accent">●</span></span></div><div class="progress-meta"><span>人格审计 / ${q[0]}</span><span class="mono">${String(current+1).padStart(2,'0')} <span class="muted">/ 30</span></span></div><div class="progress"><div style="width:${count/30*100}%"></div></div><div class="question-card"><p class="eyebrow">PROTOCOL ${String(current+1).padStart(2,'0')} / ${['ECONOMY','AUTHORITY','TECHNOLOGY','EXISTENCE','ACTION'][q[2]]}</p><h2 tabindex="-1">${q[1]}</h2><p class="quip">// ${q[4]}</p><div class="options">${['强烈反对','比较反对','中立 / 不确定','比较赞同','强烈赞同'].map((t,i)=>`<button class="option ${answers[current]===i-2?'selected':''}" data-v="${i-2}" aria-pressed="${answers[current]===i-2}"><span class="option-key">${i+1}</span>${t}<span class="radio"></span></button>`).join('')}</div><div class="question-nav"><button class="secondary" id="prev" ${current===0?'disabled':''}>← 上一题</button><span class="muted keyboard-hint">按 1–5 选择 · Enter 继续</span><button class="primary next" id="next" ${answers[current]===null?'disabled':''}>${current===29?'生成档案':'下一题'} →</button></div><p class="saved">本机自动保存 · 已完成 ${count}/30</p></div><div class="question-map" aria-label="题目导航">${answers.map((v,i)=>`<button class="${i===current?'active':''} ${v!==null?'done':''}" data-q="${i}" aria-label="第 ${i+1} 题${v!==null?'，已回答':''}" ${i===current?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p id="quiz-status" class="disclaimer" role="status">你可以随时返回修改答案。犹豫也算一种自我认识。</p></section>`;
document.querySelector('#exit').onclick=()=>go(home);document.querySelector('#prev').onclick=()=>{current--;save();go(quiz);};document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{answers[current]=Number(b.dataset.v);save();beep();quiz();document.querySelector(`[data-v="${answers[current]}"]`).focus();});document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{current=Number(b.dataset.q);save();go(quiz);});document.querySelector('#next').onclick=()=>{if(current===29){if(complete())go(result);else{current=answers.indexOf(null);save();go(quiz);document.querySelector('#quiz-status').textContent='还有未回答的题目，已为你定位。';}}else{current++;save();go(quiz);}};}
function scores(){return AXES.map((_,axis)=>Math.round(50+QUESTIONS.reduce((s,q,i)=>s+(q[2]===axis?answers[i]*q[3]:0),0)/12*50));}
function result(){if(!complete())return go(quiz);const s=scores();const archetype=s[4]>=60?(s[3]>=60?['荒诞破壁者','你知道世界是个草台班子，但还是想给它换套操作系统。','REBEL OF THE ABSURD']:['霓虹理想主义者','世界欠你一个未来。你决定不再等它主动还款。','NEON IDEALIST']):(s[3]>=60?['清醒的系统幽灵','你看穿了这场游戏，却依然每天认真上线。','GHOST IN THE SYSTEM']:['缝隙里的造梦者','在庞大的机器之间，你坚持给人性留一扇窗。','DREAMER IN THE CRACKS']);app.innerHTML=`<section class="results"><div class="quiz-top"><span class="eyebrow">AUDIT COMPLETE / 档案已解密</span><span class="accent mono">30 / 30 VERIFIED</span></div><div class="result-hero"><div><p class="eyebrow">YOUR NIGHT CITY ARCHETYPE</p><h1 tabindex="-1">${archetype[0]}</h1><p class="mono accent">${archetype[2]}</p><p class="result-quote">“${archetype[1]}”</p><span class="tag">人格不是判决书，它只是此刻的快照。</span></div><div class="result-seal">✳<span>SUBJECT<br>HUMAN, PROBABLY.</span></div></div><div class="result-grid"><article class="analysis-panel"><h2>你的思想坐标 <span class="mono">05 AXES</span></h2>${AXES.map((a,i)=>`<div class="axis"><div class="axis-title">${a.name}<span>${s[i]>=45&&s[i]<=55?'两端均衡':s[i]<50?a.left:a.right}</span></div><div class="axis-bar"><i style="left:clamp(5px,${s[i]}%,calc(100% - 5px))"></i></div><div class="axis-labels"><span>${a.left}</span><span>${a.right}</span></div></div>`).join('')}<p class="muted small">坐标是回答的相对方向，不是能力评分或人群百分位。接近中点可能代表折中、不确定，也可能是不同情境下的选择。</p></article><article class="analysis-panel"><h2>系统解读 <span>↗</span></h2>${AXES.map((a,i)=>`<div class="reading"><h3>${String(i+1).padStart(2,'0')} / ${a.name}</h3><p>${s[i]>=45&&s[i]<=55?'你的回答在两端之间保持张力。你可能更在意具体情境，而不是一套到处适用的口号。':a.note[s[i]<50?0:1]}</p></div>`).join('')}</article></div><div class="reflection"><p class="eyebrow">NEXT QUESTION / 不计分</p><h2>${s[4]>=50?'如果明天旧系统真的消失了，你愿意为新规则承担什么责任？':'如果每次修补都让系统多活一天，你修复的是人的生活，还是系统的寿命？'}</h2><p>试着找一个你强烈反对的观点，为它写出最有说服力的理由。系统不会因此扣你的分。</p></div><div class="result-actions"><button class="primary" id="export">导出人格档案 ↓</button><button class="secondary" id="review">回看答案 ↗</button><button class="text-button" id="restart">重新审计 ↻</button></div><p class="disclaimer">娱乐与自我反思测试 · 原创题目，未经心理测量学验证 · 原型由行动方式与存在立场组合，完整解读参考全部五轴。</p></section>`;document.querySelector('#review').onclick=()=>{current=0;save();go(quiz);};document.querySelector('#restart').onclick=()=>{if(confirm('重新开始会清除本机的现有答案，继续吗？')){answers=Array(30).fill(null);current=0;save();go(quiz);}};document.querySelector('#export').onclick=()=>{const content=`异格 NEON PSYCHE / 人格审计报告\n${archetype[0]}\n${archetype[1]}\n\n${AXES.map((a,i)=>`${a.name}：${a.left} 0 ← ${s[i]} → 100 ${a.right}\n${s[i]>=45&&s[i]<=55?'两端均衡，重视情境。':a.note[s[i]<50?0:1]}`).join('\n\n')}\n\n娱乐与自我反思用途，非心理诊断。结果仅描述本次回答。\n计分：每轴六题等权，按题目方向转换，线性映射至 0–100。`;const u=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='异格-人格审计报告.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};}
document.querySelector('#sound').onclick=e=>{sound=!sound;e.currentTarget.textContent=sound?'♪ ON':'♪ OFF';e.currentTarget.setAttribute('aria-pressed',sound);e.currentTarget.setAttribute('aria-label',sound?'关闭音效':'开启音效');beep();};document.querySelector('.brand').onclick=e=>{e.preventDefault();go(home);};const info=document.querySelector('#info');document.querySelector('#privacy').onclick=()=>info.showModal();document.querySelector('#close-info').onclick=()=>info.close();document.querySelector('#clear-data').onclick=()=>{answers=Array(30).fill(null);current=0;try{localStorage.removeItem(KEY);}catch{}home();document.querySelector('#clear-status').textContent='本机记录已清除。';};document.addEventListener('keydown',e=>{if(info.open||!document.querySelector('.quiz-shell')||e.altKey||e.ctrlKey||e.metaKey)return;if(/^[1-5]$/.test(e.key)){e.preventDefault();document.querySelector(`[data-v="${Number(e.key)-3}"]`)?.click();}if(e.key==='Enter'&&(e.target===document.body||e.target.closest?.('.option'))){e.preventDefault();document.querySelector('#next')?.click();}});home();
